<?php
if(PHP_SAPI!=='cli'){fwrite(STDERR,"CLI only\n");exit(1);}if(!in_array(strtolower((string)(getenv('APP_ENV')?:'local')),['local','development'],true)&&getenv('ALLOW_MAIL_TEST')!=='1'){fwrite(STDERR,"Set APP_ENV=local/development or ALLOW_MAIL_TEST=1.\n");exit(1);}require_once __DIR__.'/../../config.php';require_once __DIR__.'/../../base/NotificationPolicy.class.php';$db=new mysqli($conf['db_server'],$conf['db_username'],$conf['db_password'],$conf['db_name']);if($db->connect_error){fwrite(STDERR,"Database connection failed.\n");exit(1);}$db->query("CREATE TABLE IF NOT EXISTS game_mail_broadcasts (broadcast_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,sender_address VARCHAR(190) NOT NULL,subject VARCHAR(190) NOT NULL,body TEXT NOT NULL,recipient_count INT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$db->query("CREATE TABLE IF NOT EXISTS game_email_messages (email_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,from_uid INT NULL,from_address VARCHAR(190) NOT NULL,to_uid INT NULL,to_address VARCHAR(190) NOT NULL,subject VARCHAR(190) NOT NULL,body TEXT NOT NULL,email_type VARCHAR(16) NOT NULL DEFAULT 'broadcast',is_read TINYINT(1) NOT NULL DEFAULT 0,is_deleted TINYINT(1) NOT NULL DEFAULT 0,delivery_status VARCHAR(16) NOT NULL DEFAULT 'queued',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,sent_at DATETIME NULL,broadcast_id BIGINT UNSIGNED NULL,has_attachments TINYINT(1) NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$db->query("ALTER TABLE game_email_messages ADD COLUMN IF NOT EXISTS broadcast_id BIGINT UNSIGNED NULL, ADD COLUMN IF NOT EXISTS has_attachments TINYINT(1) NOT NULL DEFAULT 0");$db->query("CREATE TABLE IF NOT EXISTS game_email_attachments (attachment_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,email_id BIGINT UNSIGNED NOT NULL,uid INT NOT NULL,attachment_type ENUM('currency','item','equipment') NOT NULL,resource_key VARCHAR(64) NULL,asset_key VARCHAR(128) NULL,quantity BIGINT UNSIGNED NOT NULL DEFAULT 1,claimed_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_mail_attachment(email_id,attachment_type,resource_key,asset_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$db->query("CREATE TABLE IF NOT EXISTS player_mail_assets (asset_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,uid INT NOT NULL,asset_type ENUM('item','equipment') NOT NULL,asset_key VARCHAR(128) NOT NULL,quantity BIGINT UNSIGNED NOT NULL DEFAULT 0,source_email_id BIGINT UNSIGNED NULL,UNIQUE KEY uq_player_mail_asset(uid,asset_type,asset_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$users=$db->query('SELECT uid,email FROM users ORDER BY uid ASC LIMIT 2');$targets=[];while($users&&($u=$users->fetch_assoc()))$targets[]=$u;if(!$targets){fwrite(STDERR,"At least one local player is required.\n");exit(1);}$db->begin_transaction();$from='root@universecivilization.game';$subject='Mail Expansion Integration Broadcast';$body='Broadcast and attachment integration test.';$b=$db->prepare('INSERT INTO game_mail_broadcasts(sender_address,subject,body) VALUES(?,?,?)');$b->bind_param('sss',$from,$subject,$body);$b->execute();$broadcastId=(int)$db->insert_id;$ins=$db->prepare("INSERT INTO game_email_messages(from_uid,from_address,to_uid,to_address,subject,body,email_type,delivery_status,broadcast_id,has_attachments) VALUES(NULL,?,?,?,?,?,'broadcast','queued',?,1)");$att=$db->prepare('INSERT INTO game_email_attachments(email_id,uid,attachment_type,resource_key,asset_key,quantity) VALUES(?,?,?,?,?,?)');foreach($targets as $u){$to=(string)($u['email']?:('player'.$u['uid'].'@universecivilization.game'));$uid=(int)$u['uid'];$ins->bind_param('sisssi',$from,$uid,$to,$subject,$body,$broadcastId);$ins->execute();$emailId=(int)$db->insert_id;$type='item';$resource='';$asset='integration.item';$qty=3;$att->bind_param('iisssi',$emailId,$uid,$type,$resource,$asset,$qty);$att->execute();NotificationPolicy::push($db,$uid,'broadcast','Server-wide announcement',$subject,'mail-test:'.$broadcastId.':'.$uid,['email_id'=>$emailId]);}$db->commit();$q=$db->query("SELECT attachment_id,uid,email_id FROM game_email_attachments WHERE email_id=(SELECT MAX(email_id) FROM game_email_messages WHERE broadcast_id=$broadcastId) LIMIT 1");$a=$q?$q->fetch_assoc():null;if(!$a){fwrite(STDERR,"Broadcast attachment was not created.\n");exit(1);}$aid=(int)$a['attachment_id'];$uid=(int)$a['uid'];$db->begin_transaction();$lock=$db->query("SELECT * FROM game_email_attachments WHERE attachment_id=$aid AND claimed_at IS NULL FOR UPDATE");$row=$lock?$lock->fetch_assoc():null;$assetType='item';$assetKey='integration.item';$source=(int)$a['email_id'];$quantity=(int)$row['quantity'];$st=$db->prepare("INSERT INTO player_mail_assets(uid,asset_type,asset_key,quantity,source_email_id) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE quantity=quantity+VALUES(quantity)");$st->bind_param('issii',$uid,$assetType,$assetKey,$quantity,$source);$st->execute();$db->query("UPDATE game_email_attachments SET claimed_at=NOW() WHERE attachment_id=$aid AND claimed_at IS NULL");$db->commit();$verify=$db->query("SELECT claimed_at FROM game_email_attachments WHERE attachment_id=$aid");if(!$verify||!$verify->fetch_assoc()['claimed_at']){fwrite(STDERR,"Attachment claim verification failed.\n");exit(1);}echo "Mail expansion integration passed: broadcast_id=$broadcastId recipients=".count($targets)." attachment_id=$aid claimed_by_uid=$uid.\n";
?>
